import java.util.*;import java.security.SecureRandom;import java.io.*;import javax.imageio.ImageIO;import com.google.zxing.*;import com.google.zxing.client.j2se.BufferedImageLuminanceSource;import com.google.zxing.common.HybridBinarizer;import com.newview.recovery.LocalTicketQR;
public class QRVerifiedProbe {public static void main(String[] args)throws Exception{for(int i=0;i<300;i++){byte[] b=new byte[32];new SecureRandom().nextBytes(b);String p="NEWVIEW-LOCAL-TICKET:"+Base64.getUrlEncoder().withoutPadding().encodeToString(b);byte[] png=LocalTicketQR.png(p);String decoded=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new BufferedImageLuminanceSource(ImageIO.read(new ByteArrayInputStream(png))))),Map.of(DecodeHintType.TRY_HARDER,true)).getText();if(!p.equals(decoded))throw new Exception("Wrong payload");}System.out.println("300 random QR PNGs decoded exactly");}}
